examples.template:
MonarchDownloadReportButton(
    formats: [
        MonarchDownloadReportFormat({{formats.0.label}}, id: {{formats.0.id}}, description: {{formats.0.description}}),
        MonarchDownloadReportFormat({{formats.1.label}}, id: {{formats.1.id}}),
        MonarchDownloadReportFormat({{formats.2.label}}, id: {{formats.2.id}}, description: {{formats.2.description}}),
    ],
    progress: progress,
    labels: MonarchDownloadReportButtonLabels(label: {{button}})
) { _ in
    try await Task.sleep(for: .milliseconds(200))
    return .downloaded
}

